/* C2 OFF development candidate. C1/historical receipts and immutable bindings are read-only. */
SET NOCOUNT ON; SET XACT_ABORT ON; SET ANSI_NULLS ON; SET QUOTED_IDENTIFIER ON;
IF USER_NAME()<>N'dbo' OR @@TRANCOUNT<>0 OR SESSION_CONTEXT(N'ShaleClientId') IS NOT NULL OR SESSION_CONTEXT(N'PrincipalUserId') IS NOT NULL THROW 59700,'Fresh neutral owner required.',1;
IF EXISTS(SELECT 1 FROM dbo.AiProductCapability WHERE Enabled=1) OR EXISTS(SELECT 1 FROM dbo.AiExternalControlV2 WHERE Enabled=1) OR EXISTS(SELECT 1 FROM dbo.AiCimdProofControlV1 WHERE Enabled=1) OR EXISTS(SELECT 1 FROM dbo.AiCimdOAuthControlV1 WHERE Enabled=1) THROW 59700,'Drain and disable all controls first.',1;
BEGIN TRY BEGIN TRANSACTION;
DECLARE @lock int; EXEC @lock=sys.sp_getapplock @Resource=N'AiSchemaV1',@LockMode='Exclusive',@LockOwner='Transaction',@LockTimeout=3000;
IF @lock<0 THROW 59700,'Schema lock unavailable.',1;
DECLARE @DcrBatch1 nvarchar(max)=CONVERT(nvarchar(max),); EXEC sys.sp_executesql @DcrBatch1;
DECLARE @DcrBatch2 nvarchar(max)=CONVERT(nvarchar(max),); EXEC sys.sp_executesql @DcrBatch2;
CREATE TABLE dbo.AiDcrControlV3(Id tinyint NOT NULL PRIMARY KEY CHECK(Id=1),Enabled bit NOT NULL DEFAULT 0);
INSERT dbo.AiDcrControlV3 VALUES(1,0);
CREATE TABLE dbo.AiDcrRateV3(
 Kind tinyint NOT NULL CHECK(Kind BETWEEN 0 AND 2),KeyHash binary(32) NOT NULL,
 MinuteWindow bigint NOT NULL,Attempts int NOT NULL CHECK(Attempts BETWEEN 1 AND 100),
 CONSTRAINT PK_AiDcrRateV3 PRIMARY KEY(Kind,KeyHash,MinuteWindow)
);
DECLARE @DcrBatch3 nvarchar(max)=CONVERT(nvarchar(max),); EXEC sys.sp_executesql @DcrBatch3;
DECLARE @DcrBatch4 nvarchar(max)=CONVERT(nvarchar(max),); EXEC sys.sp_executesql @DcrBatch4;
DECLARE @DcrBatch5 nvarchar(max)=CONVERT(nvarchar(max),); EXEC sys.sp_executesql @DcrBatch5;
DECLARE @DcrBatch6 nvarchar(max)=CONVERT(nvarchar(max),); EXEC sys.sp_executesql @DcrBatch6;
DECLARE @DcrBatch7 nvarchar(max)=CONVERT(nvarchar(max),); EXEC sys.sp_executesql @DcrBatch7;
DECLARE @DcrBatch8 nvarchar(max)=CONVERT(nvarchar(max),); EXEC sys.sp_executesql @DcrBatch8;
DECLARE @DcrBatch9 nvarchar(max)=CONVERT(nvarchar(max),); EXEC sys.sp_executesql @DcrBatch9;
CREATE ROLE AiDcrEndpointV3 AUTHORIZATION dbo;
GRANT EXECUTE ON dbo.AiDcrAdmissionV3 TO AiDcrEndpointV3;
GRANT EXECUTE ON dbo.AiDcrRegisterApplicationV3 TO AiDcrEndpointV3;
GRANT EXECUTE ON dbo.AiDcrStatusV3 TO AiDcrEndpointV3;
DECLARE @src binary(32)=0x086cf01d99097a2a5a43d9e5a77fdf5a28443916c1795559e55aa2d8e97f0a13; EXEC sys.sp_addextendedproperty @name=N'DcrEndpointV3.Source',@value=@src,@level0type=N'SCHEMA',@level0name=N'dbo',@level1type=N'PROCEDURE',@level1name=N'AiDcrCompatibilityV3';
DECLARE @DcrBatch10 nvarchar(max)=CONVERT(nvarchar(max),); EXEC sys.sp_executesql @DcrBatch10;
DECLARE @DcrBatch11 nvarchar(max)=CONVERT(nvarchar(max),); EXEC sys.sp_executesql @DcrBatch11;
DECLARE @DcrBatch12 nvarchar(max)=CONVERT(nvarchar(max),); EXEC sys.sp_executesql @DcrBatch12;
COMMIT TRANSACTION; END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK TRANSACTION; THROW; END CATCH;
